declare class BuildConfiguration<ResultType> {
	/**
	 * List of required parameters
	 */
	public required: Set<string> = new Set

	/**
	  * List of parameters that need to be ignored.
	  */
	readonly ignores: Set<string> = new Set

	/**
	  * Collection of transformers. Each transformer is a callback function associated to a property,
	  * this gets called just before the property is assigned to the base object.
	  */
	readonly transformers: {[localPath: string]: ValueTransformer} = {}

	/**
	  * Collection of aliases. Each alias represents an alternative name for the property
	  * in the incoming object.
	  */
	readonly aliases: {[localPath: string]: string} = {}

	/**
	  * Collection of list element constructors. This is used to define how to construct
	  * the individual items of an incoming list.
	  */
	readonly listElementConstructors: {[localPath: string]: ResultType} = {}

	/**
	 * Add a required directive for one or more paths.
	 *
	 * @param paths The object paths to set as required when instantiating.
	 */
	public require(...paths: string[]): this {
		paths.forEach(path => this.required.add(path))
		return this
	}

	/**
	 * Add an ignore directive for one or more paths.
	 *
	 * @param paths The object paths to ignore when instantiating.
	 */
	public ignore(...paths: string[]): this {
		paths.forEach(path => this.ignores.add(path))
		return this
	}

	/**
	 * Add a transform directive for a given path.
	 *
	 * @param localPath The property of the typed object that needs to be transformed.
	 * @param transformer The {@link ValueTransformer} used.
	 */
	public transform(localPath: string, transformerIn: Action, transformerOut?: Action): this {
		const defaultTransformer: Action = (value) => value

		this.transformers[localPath] = {
			in: transformerIn,
			out: transformerOut ?? defaultTransformer,
		}

		return this
	}

	/**
	 * Add an alias for a given property.
	 *
	 * @param foreignPath The path of the incoming object.
	 * @param localPath The path of the typed object's property.
	 */
	public alias(foreignPath: string, localPath: string): this {
		this.aliases[localPath] = foreignPath
		return this
	}

	/**
	 * Add a list item type to let the builder know how to construct
	 * the elements of a list.
	 *
	 * @param localPath The path of the typed object's property.
	 * @param builtObject The list element as a typed object.
	 */
	public listType(localPath: string, builtObject: ResultType): this {
		this.listElementConstructors[localPath] = builtObject
		return this
	}
}

interface JSONConvertible {
	/**
	 * Convert from a generic JSON object to a typed one.
	 *
	 * @param source The object to transform.
	 * @returns A typed object populated according to the rules you defined while configuring.
	 */
	fromJSON(source: any);

	/**
	 * Convert the typed object to a JSON one by applying all the rules backwards.
	 * @param args Additional arguments
	 */
	toJSON(...args: any[]): any;
}

/**
 * Defines an object that can be automatically built from JSON data.
 *
 * Use this as the base class for your resources (ie. Users, Articles, Posts, ect.)
 */
declare abstract class BuildableResource<Type extends BuildableResource<Type> = any> implements JSONConvertible {
	/**
	 * The specified {@link BuildConfiguration} for this class.
	 */
	private resourceBuildConfiguration?: BuildConfiguration<this>

	/**
	 * The base constructor with no arguments. Your class NEEDS to have it.
	 */
	constructor() {}

	public get buildConfig(): BuildConfiguration<this> {
		if (!Object.getOwnPropertyDescriptor(this, 'resourceBuildConfiguration') && this.resourceBuildConfiguration) {
			this.resourceBuildConfiguration = deepCopy(this.resourceBuildConfiguration)

		} else if (!this.resourceBuildConfiguration) {
			this.resourceBuildConfiguration = new BuildConfiguration<this>
		}

		return this.resourceBuildConfiguration
	}

	/**
	 * Public getter for this class' current builder.
	 */
	public get build(): Builder<this> {
		const c = (this as unknown as Type).constructor.prototype.constructor
		return new Builder(c, this.buildConfig)
	}

	public fromJSON(source: any): this {
		return this.build.fromJSON(source)
	}

	public toJSON(): any {
		return this.build.toJSON(this)
	}
}

/**
 * A factory used to construct from generic types derived from {@link BuildableResource}.
 */
interface ResourceFactory<Type extends BuildableResource> {
	new(): Type;
}

/**
 * This is used to define how a class needs to be constructed from an object.
 */
declare class Builder<ResultType extends BuildableResource<ResultType>> implements JSONConvertible {
	/**
	 * The built object to populate.
	 */
	private baseObject: ResultType

	/**
	 * A {@link BuildConfiguration} containing all the instructions
	 * on how the object should be built.
	 */
	readonly buildConfig: BuildConfiguration<ResultType>

	/**
	 * Instantiates the given class thanks to a {@link ResourceFactory}.
	 *
	 * @param ctor The class that needs to be instantiated.
	 * @param buildConfig A {@link BuildConfiguration} instance (it overrides the one set in the object)
	 */
	constructor(ctor: ResourceFactory<ResultType>, buildConfig: BuildConfiguration<ResultType>|null = null) {
		this.baseObject = new ctor()
		this.buildConfig = buildConfig ?? this.baseObject.buildConfig ?? new BuildConfiguration<ResultType>
	}

	private getForeignObjectReference(localPath: string, foreignObject: any = undefined): ObjectReference {
		const foreignPath = this.buildConfig.aliases[localPath] ?? localPath
		const foreignValue = Dot.get(foreignPath, foreignObject)

		let result: ObjectReference

		if (foreignObject == undefined) {
			result = {path: foreignPath, value: null,}
		} else {
			result = {path: foreignValue != null ? foreignPath : localPath, value: foreignValue,}
		}

		result.value = Dot.get(result.path, foreignObject)

		return result
	}

	public fromJSON(source: any): ResultType {
		const target = this.baseObject
		const params = Describer.getParameters(target)

		params.forEach(param => {
			if (this.buildConfig.ignores.has(param) || !params.includes(param)) {
				return
			}

			const foreignObject = this.getForeignObjectReference(param, source)

			if (!source || !foreignObject.value) {
				if (this.buildConfig.required.has(param)) {
					throw new Error("Invalid input object, missing required parameter: " + param)
				} else return
			}

			if (target[param] instanceof BuildableResource) {
				target[param] = target[param].build.fromJSON(foreignObject.value)
			} else if (Array.isArray(target[param])) {
				const list: any[] = foreignObject.value

				target[param] = list.map((item: any, index: number) => {
					const listClassElement = this.buildConfig.listElementConstructors[param]
					if(listClassElement) {
						const listElementClassBuilder = listClassElement.build
						return listElementClassBuilder.fromJSON(item)
					} else if (!this.buildConfig.required.has(param) && foreignObject.value) {
						return foreignObject.value[index]
					}
				})
			} else {
				if (this.buildConfig.transformers[param]){
					target[param] = this.buildConfig.transformers[param].in(foreignObject.value)
				} else {
					target[param] = foreignObject.value
				}
			}
		})

		return deepCopy(target) as ResultType
	}

	public toJSON(source: ResultType): any {
		const params = Describer.getParameters(source)
		const result = {}

		params.forEach(param => {
			const foreignObject = this.getForeignObjectReference(param)
			let valueToAssign: any = undefined

			if (this.buildConfig.ignores.has(param)) {
				return
			}

			if (source[param] instanceof BuildableResource) {
				valueToAssign = source[param].build.toJSON(source[param])
			} else if (Array.isArray(source[param])) {
				const list: any[] = source[param]

				valueToAssign = list.map((item: any, index: number) => {
					const listClassElement = this.buildConfig.listElementConstructors[param]
					if(listClassElement) {
						const listElementClassBuilder = listClassElement.build
						return listElementClassBuilder.toJSON(item)
					} else if (source.hasOwnProperty(param)) {
						const x = Dot.get(foreignObject.path, result)
						return this.buildConfig.transformers[param] ? this.buildConfig.transformers[param].out(x[index]) : x[index]
					}
				})
			} else {
				valueToAssign = this.buildConfig.transformers[param] ? this.buildConfig.transformers[param].out(source[param]) : source[param]
			}

			Dot.assign(foreignObject.path, result, valueToAssign)
		})

		delete result["resourceBuildConfiguration"] // FIXME Magic number

		return result
	}
}

declare const Resource = resourceDecorator.Resource
declare const Alias = resourceDecorator.Alias
declare const Transform = resourceDecorator.Transform
declare const Ignore = resourceDecorator.Ignore
declare const Required = resourceDecorator.Required
declare const ListOf = resourceDecorator.ListOf

declare const decorators_Resource: typeof Resource;
declare const decorators_Alias: typeof Alias;
declare const decorators_Transform: typeof Transform;
declare const decorators_Ignore: typeof Ignore;
declare const decorators_Required: typeof Required;
declare const decorators_ListOf: typeof ListOf;
declare namespace decorators {
  export {
    decorators_Resource as Resource,
    decorators_Alias as Alias,
    decorators_Transform as Transform,
    decorators_Ignore as Ignore,
    decorators_Required as Required,
    decorators_ListOf as ListOf,
  };
}

export { BuildConfiguration, BuildableResource, Builder, decorators as Properties };
